export interface GenerateAsyncPrevious<TOutput, TFeedback> {
  readonly output: TOutput;
  readonly feedback: TFeedback;
}

export interface GenerateAsyncContext<TOutput, TFeedback> {
  readonly index: number;
  readonly previous?: GenerateAsyncPrevious<TOutput, TFeedback>;
}

export type GenerateAsyncExecutor<TInput, TOutput, TFeedback> = (
  input: TInput,
  context: GenerateAsyncContext<TOutput, TFeedback>,
) => Promise<TOutput> | TOutput;
